/// Position in the buffer counted in Unicode scalar values (ropey's native unit).
#[derive(Copy, Clone, PartialEq, Eq, PartialOrd, Ord, Hash, Debug, Default)]
pub struct Offset(pub usize);

/// Half-open range of offsets; `start <= end` is an invariant enforced by `new`.
#[derive(Copy, Clone, PartialEq, Eq, Hash, Debug)]
pub struct CharRange { start: Offset, end: Offset }
impl CharRange {
    pub fn new(a: Offset, b: Offset) -> Self; // orders the two
    pub fn start(&self) -> Offset; pub fn end(&self) -> Offset;
    pub fn len(&self) -> usize; pub fn is_empty(&self) -> bool;
    pub fn contains(&self, o: Offset) -> bool;
}

/// Derived view of an Offset. `col` is in chars from line start.
#[derive(Copy, Clone, PartialEq, Eq, PartialOrd, Ord, Hash, Debug)]
pub struct LineCol { pub line: u32, pub col: u32 }

/// Monotonic edit counter. 0 for a new or freshly loaded buffer. Never decreases, not even on undo.
#[derive(Copy, Clone, PartialEq, Eq, PartialOrd, Ord, Hash, Debug, Default)]
pub struct Revision(pub u64);

/// One replacement against the pre-transaction text. Insert: `old` empty. Delete: `new` empty.
#[derive(Clone, PartialEq, Eq, Debug)]
pub struct Edit { pub start: Offset, pub old: String, pub new: String }
impl Edit {
    pub fn insert(at: Offset, text: impl Into<String>) -> Self;
    pub fn delete(at: Offset, old: impl Into<String>) -> Self;
    pub fn old_end(&self) -> Offset; // start + old char count
    pub fn new_end(&self) -> Offset; // start + new char count
    pub fn delta(&self) -> isize;
    pub fn invert(&self) -> Edit; // swaps old and new
}

/// Edits sorted by `start`, pairwise non-overlapping, all relative to the same pre-state.
#[derive(Clone, PartialEq, Eq, Debug, Default)]
pub struct Transaction { edits: Vec<Edit> }
impl Transaction {
    pub fn new(edits: Vec<Edit>) -> Result<Self, TransactionError>; // sorts, rejects overlap
    pub fn single(edit: Edit) -> Self;
    pub fn edits(&self) -> &[Edit];
    pub fn invert(&self) -> Transaction; // valid against the post-state
    pub fn is_empty(&self) -> bool;
}

#[derive(Debug, PartialEq, Eq)]
pub enum TransactionError { Overlap { first: usize, second: usize } }

pub struct TextBuffer { text: ropey::Rope, revision: Revision }
impl TextBuffer {
    pub fn new() -> Self;
    pub fn from_str(s: &str) -> Self;
    pub fn text(&self) -> &ropey::Rope;
    pub fn snapshot(&self) -> ropey::Rope; // O(1) persistent clone for off-thread readers
    pub fn revision(&self) -> Revision;
    pub fn len(&self) -> Offset; // chars
    pub fn line_count(&self) -> u32; // >= 1; a buffer always has a last line
    pub fn line_col(&self, at: Offset) -> LineCol;
    pub fn offset(&self, at: LineCol) -> Offset; // clamps col to line length
    pub fn slice(&self, r: CharRange) -> ropey::RopeSlice<'_>;
    /// Validates every edit against the current text, applies all, bumps revision by exactly 1.
    pub fn apply(&mut self, tx: &Transaction) -> Result<Revision, ApplyError>;
}

#[derive(Debug, PartialEq, Eq)]
pub enum ApplyError {
    OutOfBounds { edit: usize, end: Offset, len: Offset },
    OldTextMismatch { edit: usize, expected: String, found: String },
}
